bool PageHandlerStubDispatch::AcceptWithResponder(
    PageHandler* impl,
    mojo::Message* message,
    std::unique_ptr<mojo::internal::ResponderThunk> responder) {
  [[maybe_unused]] const bool message_is_sync =
      message->has_flag(mojo::Message::kFlagIsSync);
  [[maybe_unused]] const uint64_t request_id = message->request_id();
  switch (static_cast<messages::PageHandler>(message->header()->name)) {
    case messages::PageHandler::kGetURLVisits: {
      internal::PageHandler_GetURLVisits_Params_Data* params =
          reinterpret_cast<
              internal::PageHandler_GetURLVisits_Params_Data*>(
                  message->mutable_payload());
      

      // Validation for PageHandler.0
      bool success = true;
      PageHandler_GetURLVisits_ParamsDataView input_data_view(params, message);
      
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            PageHandler::Name_, 0, false);
        return false;
      }
      auto callback =
          PageHandler_GetURLVisits_ProxyToResponder::CreateCallback(
              *message, std::move(responder));
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->GetURLVisits(std::move(callback));
      return true;
    }
    case messages::PageHandler::kDismissURLVisit: {
      break;
    }
    case messages::PageHandler::kRestoreURLVisit: {
      break;
    }
    case messages::PageHandler::kRecordAction: {
      break;
    }
  }
  return false;
}
