PageHandlerAsyncWaiter::PageHandlerAsyncWaiter(
    PageHandler* proxy) : proxy_(proxy) {}

PageHandlerAsyncWaiter::~PageHandlerAsyncWaiter() = default;


void PageHandlerAsyncWaiter::GetURLVisits(
    std::vector<::ntp::most_relevant_tab_resumption::mojom::URLVisitPtr>* out_url_visits) {
  base::RunLoop loop;
  proxy_->GetURLVisits(
      base::BindOnce(
          [](base::RunLoop* loop,
             std::vector<::ntp::most_relevant_tab_resumption::mojom::URLVisitPtr>* out_url_visits
,
             std::vector<::ntp::most_relevant_tab_resumption::mojom::URLVisitPtr> url_visits) {*out_url_visits = std::move(url_visits);
            loop->Quit();
          },
          &loop,
          out_url_visits));
  loop.Run();
}

std::vector<::ntp::most_relevant_tab_resumption::mojom::URLVisitPtr> PageHandlerAsyncWaiter::GetURLVisits(
    ) {
  std::vector<::ntp::most_relevant_tab_resumption::mojom::URLVisitPtr> async_wait_result;
  GetURLVisits(&async_wait_result);
  return async_wait_result;
}






